1	package darksafe
2	
3	import (
4		"bytes"
5		"encoding/json"
6		"errors"
7		"fmt"
8		"io"
9		"sort"
10		"strings"
11	)
12	
13	// Reason constants for clusters that cannot enter a release plan.
14	const (
15		ReasonDisabled          = "集群已停用"
16		ReasonExcludeMatched    = "命中排除条件"
17		ReasonIncludeNotMatched = "未命中包含条件"
18	)
19	
20	// LabelCondition is a set of exact key-value matches; all must match.
21	type LabelCondition map[string]string
22	
23	// Cluster is a candidate target for a release.
24	type Cluster struct {
25		ID       string
26		Disabled bool
27		Tags     map[string]string
28	}
29	
30	// ReleasePlanInput describes an application release to plan offline.
31	type ReleasePlanInput struct {
32		App       string
33		Revision  string
34		Image     string
35		BatchSize int
36		Clusters  []Cluster
37		Include   []LabelCondition
38		Exclude   []LabelCondition
39	}
40	
41	// AppInfo identifies the application being released.
42	type AppInfo struct {
43		Name     string `json:"name"`
44		Revision string `json:"revision"`
45		Image    string `json:"image"`
46	}
47	
48	// Batch is a sequentially numbered group of cluster IDs.
49	type Batch struct {
50		Index    int      `json:"index"`
51		Clusters []string `json:"clusters"`
52	}
53	
54	// ExcludedCluster explains why a cluster is not in the plan.
55	type ExcludedCluster struct {
56		ID     string `json:"id"`
57		Reason string `json:"reason"`
58	}
59	
60	// ReleasePlan is the deterministic offline release plan.
61	type ReleasePlan struct {
62		App      AppInfo           `json:"app"`
63		Batches  []Batch           `json:"batches"`
64		Excluded []ExcludedCluster `json:"excluded"`
65	}
66	
67	// ParseReleaseInput reads a release plan document and validates its fields.
68	// Every JSON object in the document — including unknown fields and their
69	// nested objects — must have distinct member names; a name appearing twice
70	// (even with the same value, or via equivalent Unicode escapes) is rejected
71	// before any business validation runs.
72	func ParseReleaseInput(data []byte) (ReleasePlanInput, error) {
73		if err := checkDuplicateMembers(data); err != nil {
74			return ReleasePlanInput{}, err
75		}
76		dec := json.NewDecoder(bytes.NewReader(data))
77		dec.UseNumber()
78		var doc map[string]any
79		if err := dec.Decode(&doc); err != nil {
80			return ReleasePlanInput{}, fmt.Errorf("JSON 格式错误: %w", err)
81		}
82		if dec.More() {
83			return ReleasePlanInput{}, errors.New("JSON 格式错误: 文档包含多余内容")
84		}
85		return buildReleaseInput(doc)
86	}
87	
88	// duplicateMemberError reports a JSON object whose member name appears more
89	// than once. Path is a JSONPath-style location: "$" for the document root,
90	// "$.clusters[1]" for a cluster, "$.clusters[0].tags" for a tag object,
91	// "$.include[2]" / "$.exclude[1]" for a condition, and "$.foo.bar[0]" for
92	// objects nested inside unknown fields.
93	type duplicateMemberError struct {
94		field string
95		path  string
96	}
97	
98	func (e *duplicateMemberError) Error() string {
99		return fmt.Sprintf("JSON 对象存在重复成员: 字段 %q 重复出现于 %s", e.field, e.path)
100	}
101	
102	// checkDuplicateMembers walks every JSON object in data and rejects objects
103	// with duplicate member names. Names are compared after JSON decoding, so
104	// "env" and "env" are the same name while "env" and "ENV", or
105	// " env" and "env", are different. The first duplicate encountered in file
106	// order is reported: the walk is depth-first in document order, so the
107	// second occurrence that appears earliest wins, regardless of value type.
108	func checkDuplicateMembers(data []byte) error {
109		dec := json.NewDecoder(bytes.NewReader(data))
110		if err := walkJSONValue(dec, "$"); err != nil {
111			return err
112		}
113		if _, err := dec.Token(); err != io.EOF {
114			if err == nil {
115				return errors.New("JSON 格式错误: 文档包含多余内容")
116			}
117			return fmt.Errorf("JSON 格式错误: %w", err)
118		}
119		return nil
120	}
121	
122	// walkJSONValue reads one complete JSON value whose first token has not been
123	// consumed yet.
124	func walkJSONValue(dec *json.Decoder, path string) error {
125		tok, err := dec.Token()
126		if err != nil {
127			if err == io.EOF {
128				return errors.New("JSON 格式错误: 文档为空")
129			}
130			return fmt.Errorf("JSON 格式错误: %w", err)
131		}
132		return walkJSONValueToken(dec, path, tok)
133	}
134	
135	// walkJSONValueToken reads the remainder of a value given its first token.
136	func walkJSONValueToken(dec *json.Decoder, path string, tok json.Token) error {
137		if d, ok := tok.(json.Delim); ok {
138			switch d {
139			case '{':
140				return walkJSONObject(dec, path)
141			case '[':
142				return walkJSONArray(dec, path)
143			default:
144				return fmt.Errorf("JSON 格式错误: 意外的分隔符 %q", d)
145			}
146		}
147		return nil // scalar value (string, number, bool, null)
148	}
149	
150	func walkJSONObject(dec *json.Decoder, path string) error {
151		seen := make(map[string]struct{})
152		for {
153			tok, err := dec.Token()
154			if err != nil {
155				if err == io.EOF {
156					return errors.New("JSON 格式错误: 对象未闭合")
157				}
158				return fmt.Errorf("JSON 格式错误: %w", err)
159			}
160			if d, ok := tok.(json.Delim); ok {
161				if d == '}' {
162					return nil
163				}
164				return fmt.Errorf("JSON 格式错误: 意外的分隔符 %q", d)
165			}
166			key, ok := tok.(string)
167			if !ok {
168				return errors.New("JSON 格式错误: 对象成员名必须是字符串")
169			}
170			if _, dup := seen[key]; dup {
171				return &duplicateMemberError{field: key, path: path}
172			}
173			seen[key] = struct{}{}
174			vtok, err := dec.Token()
175			if err != nil {
176				if err == io.EOF {
177					return errors.New("JSON 格式错误: 缺少成员值")
178				}
179				return fmt.Errorf("JSON 格式错误: %w", err)
180			}
181			if err := walkJSONValueToken(dec, path+"."+key, vtok); err != nil {
182				return err
183			}
184		}
185	}
186	
187	func walkJSONArray(dec *json.Decoder, path string) error {
188		for i := 0; ; i++ {
189			tok, err := dec.Token()
190			if err != nil {
191				if err == io.EOF {
192					return errors.New("JSON 格式错误: 数组未闭合")
193				}
194				return fmt.Errorf("JSON 格式错误: %w", err)
195			}
196			if d, ok := tok.(json.Delim); ok && d == ']' {
197				return nil
198			}
199			if err := walkJSONValueToken(dec, fmt.Sprintf("%s[%d]", path, i), tok); err != nil {
200				return err
201			}
202		}
203	}
204	
205	func buildReleaseInput(doc map[string]any) (ReleasePlanInput, error) {
206		app, err := requiredString(doc, "app")
207		if err != nil {
208			return ReleasePlanInput{}, err
209		}
210		revision, err := requiredString(doc, "revision")
211		if err != nil {
212			return ReleasePlanInput{}, err
213		}
214		image, err := requiredString(doc, "image")
215		if err != nil {
216			return ReleasePlanInput{}, err
217		}
218		batchSize, err := positiveInt(doc, "batchSize")
219		if err != nil {
220			return ReleasePlanInput{}, err
221		}
222		clusters, err := parseClusters(doc["clusters"])
223		if err != nil {
224			return ReleasePlanInput{}, err
225		}
226		include, err := parseConditions(doc["include"], "include")
227		if err != nil {
228			return ReleasePlanInput{}, err
229		}
230		exclude, err := parseConditions(doc["exclude"], "exclude")
231		if err != nil {
232			return ReleasePlanInput{}, err
233		}
234	
235		return ReleasePlanInput{
236			App:       app,
237			Revision:  revision,
238			Image:     image,
239			BatchSize: batchSize,
240			Clusters:  clusters,
241			Include:   include,
242			Exclude:   exclude,
243		}, nil
244	}
245	
246	// ValidateReleaseInput checks that a release configuration is well-formed:
247	// app/revision/image are non-empty, batchSize is a positive integer, cluster
248	// IDs are unique across every candidate (including disabled and filtered-out
249	// clusters), and tag/condition keys are non-empty. Errors name the field and
250	// the position in its list; within a cluster the ID is checked before its
251	// tags, and tag keys are examined in ascending order so repeated calls report
252	// the same error. The input is never mutated. MakeReleasePlan calls this
253	// automatically; library callers may use it to validate without planning.
254	func ValidateReleaseInput(in ReleasePlanInput) error {
255		if strings.TrimSpace(in.App) == "" {
256			return errors.New(`字段 "app" 不能为空或只含空白`)
257		}
258		if strings.TrimSpace(in.Revision) == "" {
259			return errors.New(`字段 "revision" 不能为空或只含空白`)
260		}
261		if strings.TrimSpace(in.Image) == "" {
262			return errors.New(`字段 "image" 不能为空或只含空白`)
263		}
264		if in.BatchSize <= 0 {
265			return errors.New(`字段 "batchSize" 必须是正整数`)
266		}
267		seen := make(map[string]struct{}, len(in.Clusters))
268		for i, c := range in.Clusters {
269			if strings.TrimSpace(c.ID) == "" {
270				return fmt.Errorf("clusters[%d]: 字段 %q 不能为空或只含空白", i, "id")
271			}
272			if _, dup := seen[c.ID]; dup {
273				return fmt.Errorf("clusters[%d]: 重复的集群标识 %q", i, c.ID)
274			}
275			seen[c.ID] = struct{}{}
276			if err := validateTagKeys(i, c.Tags); err != nil {
277				return err
278			}
279		}
280		if err := validateConditionKeys("include", in.Include); err != nil {
281			return err
282		}
283		if err := validateConditionKeys("exclude", in.Exclude); err != nil {
284			return err
285		}
286		return nil
287	}
288	
289	// validateTagKeys checks tag keys in ascending order for deterministic errors.
290	func validateTagKeys(clusterIndex int, tags map[string]string) error {
291		keys := make([]string, 0, len(tags))
292		for k := range tags {
293			keys = append(keys, k)
294		}
295		sort.Strings(keys)
296		for _, k := range keys {
297			if k == "" {
298				return fmt.Errorf("clusters[%d] 的标签键不能为空", clusterIndex)
299			}
300		}
301		return nil
302	}
303	
304	// validateConditionKeys checks that every condition is non-empty and has only
305	// non-empty keys; conditions are visited in original order and keys in
306	// ascending order for deterministic errors.
307	func validateConditionKeys(field string, conds []LabelCondition) error {
308		for i, cond := range conds {
309			if len(cond) == 0 {
310				return fmt.Errorf("%s[%d] 不能为空条件对象", field, i)
311			}
312			keys := make([]string, 0, len(cond))
313			for k := range cond {
314				keys = append(keys, k)
315			}
316			sort.Strings(keys)
317			for _, k := range keys {
318				if k == "" {
319					return fmt.Errorf("%s[%d] 的标签键不能为空", field, i)
320				}
321			}
322		}
323		return nil
324	}
325	
326	func requiredString(doc map[string]any, field string) (string, error) {
327		v, ok := doc[field]
328		if !ok {
329			return "", fmt.Errorf("缺少必需字段 %q", field)
330		}
331		s, ok := v.(string)
332		if !ok {
333			return "", fmt.Errorf("字段 %q 必须是字符串", field)
334		}
335		if strings.TrimSpace(s) == "" {
336			return "", fmt.Errorf("字段 %q 不能为空或只含空白", field)
337		}
338		return s, nil
339	}
340	
341	func positiveInt(doc map[string]any, field string) (int, error) {
342		v, ok := doc[field]
343		if !ok {
344			return 0, fmt.Errorf("缺少必需字段 %q", field)
345		}
346		n, ok := v.(json.Number)
347		if !ok {
348			return 0, fmt.Errorf("字段 %q 必须是正整数", field)
349		}
350		i, err := n.Int64()
351		if err != nil || i <= 0 {
352			return 0, fmt.Errorf("字段 %q 必须是正整数", field)
353		}
354		return int(i), nil
355	}
356	
357	func parseClusters(v any) ([]Cluster, error) {
358		if v == nil {
359			return nil, errors.New("缺少必需字段 \"clusters\"")
360		}
361		raw, ok := v.([]any)
362		if !ok {
363			return nil, errors.New("字段 \"clusters\" 必须是数组")
364		}
365		clusters := make([]Cluster, 0, len(raw))
366		seen := make(map[string]bool)
367		for i, item := range raw {
368			obj, ok := item.(map[string]any)
369			if !ok {
370				return nil, fmt.Errorf("clusters[%d] 必须是对象", i)
371			}
372			id, err := requiredString(obj, "id")
373			if err != nil {
374				return nil, fmt.Errorf("clusters[%d]: %w", i, err)
375			}
376			if seen[id] {
377				return nil, fmt.Errorf("clusters[%d]: 重复的集群标识 %q", i, id)
378			}
379			seen[id] = true
380	
381			disabled := false
382			if dv, present := obj["disabled"]; present {
383				b, ok := dv.(bool)
384				if !ok {
385					return nil, fmt.Errorf("集群 %q 的 \"disabled\" 必须是布尔值", id)
386				}
387				disabled = b
388			}
389	
390			tags := map[string]string{}
391			if tv, present := obj["tags"]; present {
392				tm, ok := tv.(map[string]any)
393				if !ok {
394					return nil, fmt.Errorf("集群 %q 的 \"tags\" 必须是对象", id)
395				}
396				keys := make([]string, 0, len(tm))
397				for k := range tm {
398					keys = append(keys, k)
399				}
400				sort.Strings(keys)
401				for _, k := range keys {
402					if k == "" {
403						return nil, fmt.Errorf("集群 %q 的标签键不能为空", id)
404					}
405					sv, ok := tm[k].(string)
406					if !ok {
407						return nil, fmt.Errorf("集群 %q 的标签 %q 值必须是字符串", id, k)
408					}
409					tags[k] = sv
410				}
411			}
412	
413			clusters = append(clusters, Cluster{ID: id, Disabled: disabled, Tags: tags})
414		}
415		return clusters, nil
416	}
417	
418	func parseConditions(v any, field string) ([]LabelCondition, error) {
419		if v == nil {
420			return []LabelCondition{}, nil
421		}
422		raw, ok := v.([]any)
423		if !ok {
424			return nil, fmt.Errorf("字段 %q 必须是条件数组", field)
425		}
426		conds := make([]LabelCondition, 0, len(raw))
427		for i, item := range raw {
428			obj, ok := item.(map[string]any)
429			if !ok {
430				return nil, fmt.Errorf("%s[%d] 必须是对象", field, i)
431			}
432			if len(obj) == 0 {
433				return nil, fmt.Errorf("%s[%d] 不能为空条件对象", field, i)
434			}
435			cond := LabelCondition{}
436			keys := make([]string, 0, len(obj))
437			for k := range obj {
438				keys = append(keys, k)
439			}
440			sort.Strings(keys)
441			for _, k := range keys {
442				if k == "" {
443					return nil, fmt.Errorf("%s[%d] 的标签键不能为空", field, i)
444				}
445				sv, ok := obj[k].(string)
446				if !ok {
447					return nil, fmt.Errorf("%s[%d] 的标签 %q 值必须是字符串", field, i, k)
448				}
449				cond[k] = sv
450			}
451			conds = append(conds, cond)
452		}
453		return conds, nil
454	}
455	
456	// MakeReleasePlan selects available clusters, orders them by ID, and splits
457	// them into batches. It validates the input first and never mutates it.
458	func MakeReleasePlan(in ReleasePlanInput) (ReleasePlan, error) {
459		if err := ValidateReleaseInput(in); err != nil {
460			return ReleasePlan{}, err
461		}
462		if len(in.Clusters) == 0 {
463			return ReleasePlan{}, errors.New("没有可发布的集群：未提供候选集群")
464		}
465	
466		selected := []string{}
467		excluded := []ExcludedCluster{}
468		for _, c := range in.Clusters {
469			switch {
470			case c.Disabled:
471				excluded = append(excluded, ExcludedCluster{ID: c.ID, Reason: ReasonDisabled})
472			case matchesAny(c.Tags, in.Exclude):
473				excluded = append(excluded, ExcludedCluster{ID: c.ID, Reason: ReasonExcludeMatched})
474			case len(in.Include) > 0 && !matchesAny(c.Tags, in.Include):
475				excluded = append(excluded, ExcludedCluster{ID: c.ID, Reason: ReasonIncludeNotMatched})
476			default:
477				selected = append(selected, c.ID)
478			}
479		}
480	
481		sort.Strings(selected)
482		sort.Slice(excluded, func(i, j int) bool { return excluded[i].ID < excluded[j].ID })
483	
484		if len(selected) == 0 {
485			var b strings.Builder
486			b.WriteString("没有符合规则的可用集群，各候选集群未入选原因：")
487			for _, e := range excluded {
488				b.WriteString("\n  ")
489				b.WriteString(e.ID)
490				b.WriteString("：")
491				b.WriteString(e.Reason)
492			}
493			return ReleasePlan{}, errors.New(b.String())
494		}
495	
496		batches := []Batch{}
497		for i := 0; i < len(selected); i += in.BatchSize {
498			end := i + in.BatchSize
499			if end > len(selected) {
500				end = len(selected)
501			}
502			batches = append(batches, Batch{Index: len(batches) + 1, Clusters: selected[i:end]})
503		}
504	
505		return ReleasePlan{
506			App:      AppInfo{Name: in.App, Revision: in.Revision, Image: in.Image},
507			Batches:  batches,
508			Excluded: excluded,
509		}, nil
510	}
511	
512	func matchesAny(tags map[string]string, conditions []LabelCondition) bool {
513		for _, cond := range conditions {
514			if matchesAll(tags, cond) {
515				return true
516			}
517		}
518		return false
519	}
520	
521	func matchesAll(tags map[string]string, cond LabelCondition) bool {
522		for k, v := range cond {
523			tv, ok := tags[k]
524			if !ok || tv != v {
525				return false
526			}
527		}
528		return true
529	}
530

